    var jseval = "eval"+ str[1]+window.atob(str[2])+"\'.split(\'||\'),0,{}))"
    eval("("+jseval+")");
    var list = mhInfo.images;
   var ul = mhInfo.host.replace("lineinfo","kingwar");
    var piclist = new Array([list.length]);
    for (var i = 0; i < list.length; i++) {
        piclist[i] = ul + mhInfo.path + list[i] + "-webp";
    }
    return piclist;
}

